  def self.keys = LIBRARY.keys
  def self.label(key) = LIBRARY.dig(key.to_s, :label)
  def self.exists?(key) = LIBRARY.key?(key.to_s)
  def self.options = LIBRARY.map { |k, v| [v[:label], k] }

  # Ilustraciones que rotan en bloques con varios elementos
  ROTATION = %w[camara dron calendario mensaje luces edicion foto estrella].freeze
  def self.cycle(index) = ROTATION[index % ROTATION.size]

  def self.svg(key, klass: nil, title: nil)
    item = LIBRARY[key.to_s] or return ""
    label = title ? %( role="img" aria-label="#{ERB::Util.h(title)}") : %( aria-hidden="true")
    %(<svg class="illus illus-#{key} #{klass}" viewBox="0 0 240 180" fill="none" stroke="currentColor" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"#{label}>#{item[:svg]}</svg>)
  end
end
